#include "api/client.h"
#include <assert.h>
static int got;static ApiError result;
static void response(void *ctx,const ApiResponse *r){(void)ctx;got=1;result=r->error;}
int main(int argc,char **argv){assert(argc==3);ApiClient a;api_init(&a,atoi(argv[1]));assert(!api_send(&a,API_BROWSE,API_ITEMS,"GET",argv[2],NULL,150));uint64_t start=ui_now();while(!got&&ui_now()-start<2000){api_pump(&a,ui_now(),response,NULL);struct timespec t={0,1000000};nanosleep(&t,NULL);}assert(got);if(!strcmp(argv[2],"/slow"))assert(result==API_TIMEOUT);else if(!strcmp(argv[2],"/short")||!strcmp(argv[2],"/huge-header"))assert(result==API_MALFORMED);else assert(result==API_OK);assert(ui_now()-start<1500);assert(!api_busy(&a,API_BROWSE));assert(api_send(&a,API_BROWSE,API_ITEMS,"GET","https://thirdparty.invalid/",NULL,10)<0);assert(!api_send(&a,API_BROWSE,API_ITEMS,"GET","/slow",NULL,100));api_cancel(&a,API_BROWSE);assert(!api_busy(&a,API_BROWSE));api_close(&a);puts("PASS bounded asynchronous transport and cancellation");return 0;}
